{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Measure BB Annual General Adjustment 5% cap","requirement":"The Berkeley Rent Board's annual general adjustment (AGA) for fully covered units is capped at a maximum of 5%; if the formula yields more, the approved AGA may be no more than 5%. Banked unused AGAs may still raise rent to the ceiling.","key_value":"5% maximum annual AGA","coverage_conditions":"Rental units fully covered by Berkeley's Rent Ordinance; government-owned or -subsidized units are now fully or partially covered and subject to a rent ceiling.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"The maximum AGA is 5%. This means that, if the formula in the Rent Ordinance results in an AGA that is greater than 5%, the AGA approved by the Board for that year can be no more than 5%.","interaction":"Federal or state law prohibits rent control for certain subsidized unit types, which are only partially covered, so a rent ceiling may not apply.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB just cause eviction changes","requirement":"Landlords of covered units may evict only for just cause. Nonpayment eviction requires one month's Fair Market Rent in rental debt; failure to sign a substantially similar lease is no longer cause. Eviction notices are due to the Rent Board within three business days.","key_value":"1 month's Fair Market Rent nonpayment threshold","coverage_conditions":"Tenants in units fully or partially covered by Berkeley's Rent Ordinance, including government-owned or -subsidized units.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Eviction for nonpayment of rent is no longer allowed for rental debt less than one month of the Fair Market Rent for the unit","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
